<script>
  import { onMount, tick } from 'svelte';
  import NumberBoard from './NumberBoard.svelte';
  import Operators from './Operators.svelte';
  import ModePicker from './ModePicker.svelte';
  import QuestionProgress from './QuestionProgress.svelte';
  import SummaryContent from './SummaryContent.svelte';
  import Feedback from './Feedback.svelte';
  import Explanation from './Explanation.svelte';
  import MethodsContent from './MethodsContent.svelte';
  import MapContent from './MapContent.svelte';
  import './game.css';
  let root, play, analysis, mapDialog, helpDialog, methodsDialog, summaryDialog;
  let cards = $state();
  let controller;
  let view = $state({ board: null, modes: [], progress: [], hintHidden:true, analysisHidden:true, moveDetailsHidden:true, practiceNoteHidden:true, roundReviewBtnHidden:true, hintDisabled:true, revealDisabled:true, undoDisabled:true, restartDisabled:true });
  let loadError = $state('');
  const act = name => controller?.action(name);
  const close = name => controller?.closeDialog(name);
  function dismissBackdrop(event, name) {
    if (event.target !== event.currentTarget) return;
    const r = event.currentTarget.getBoundingClientRect();
    if (event.clientX<r.left || event.clientX>r.right || event.clientY<r.top || event.clientY>r.bottom) close(name);
  }
  onMount(() => {
    let disposed = false;
    import('./engine.js').then(({ createGame }) => {
      if (disposed) return;
      const dialogs = { mapDialog, helpDialog, methodsDialog, summaryDialog };
      controller = createGame(patch => { view = { ...view, ...patch }; }, {
        openDialog: name => { if (!dialogs[name].open) dialogs[name].showModal(); },
        closeDialog: name => dialogs[name].close(),
        scrollTo: name => tick().then(() => { if (!disposed) (name === 'play' ? play : analysis)?.scrollIntoView({behavior:'smooth',block:'start'}); }),
        capturePointer: id => { try { cards?.setPointerCapture(id); } catch {} },
        releasePointer: id => { try { if(cards?.hasPointerCapture(id)) cards.releasePointerCapture(id); } catch {} },
        hitTile: (x,y) => { const tile = document.elementFromPoint(x,y)?.closest('[data-tile]'); return tile && root.contains(tile) ? Number(tile.dataset.tile) : null; },
      });
      controller.visibility(document.hidden);
    }).catch(() => { if (!disposed) loadError = '游戏暂时加载失败，请刷新重试。原有进度仍保存在此浏览器中。'; });
    return () => { disposed = true; controller?.destroy(); controller = undefined; };
  });
</script>
<svelte:window onpointermove={event => controller?.dragMove(event)} onpointerup={event => controller?.dragUp(event)} onpointercancel={event => controller?.dragCancel(event)} onkeydown={event => {if(event.key==='Escape')controller?.escape();}} onpagehide={() => controller?.pageHide()} />
<svelte:document onvisibilitychange={() => controller?.visibility(document.hidden)} />
<svelte:head><title>24点 · 数字探险家</title><meta name="theme-color" content="#16766b" /></svelte:head>
<div class="twenty-four-game" bind:this={root}>
{#if loadError}<p role="alert">{loadError}</p>{/if}

<header><nav><div class="brand"><div class="brand-icon">24</div><div><strong>数字探险家</strong><small>MAKE 24 · MAKE IT FUN</small></div></div><div class="nav-actions"><button class="ghost" id="soundBtn" onclick={() => act("soundBtn")} aria-pressed={view.soundPressed ?? true}>{view.soundLabel ?? "🔊 声音开"}</button><button class="ghost" id="helpBtn" onclick={() => act("helpBtn")}>玩法说明</button></div></nav></header>
<main class="wrap"><section class="intro"><div><div class="eyebrow">A LITTLE MATH, A BIG ADVENTURE</div><h1>点一点，合成 24<span style="color:var(--orange)">.</span></h1><p class="sub">不用打字，动动小手，试试你的好点子。</p></div><div class="overall"><div><b id="totalStars">{view.totalStars ?? "0"}</b><small>✦ 探险星星</small></div><div class="total-level"><b id="totalDone">{view.totalDone ?? 0}<span style="font-size:13px;color:#9aa794"> / 50</span></b><small>已完成关卡</small></div></div></section>
<section class="mode-picker"><ModePicker modes={view.modes} onchoose={mode => controller?.changeMode(mode)} /><p>切换模式会重新开始本关，历史星星保留。</p></section><div class="layout"><section class="play" class:bounce={view.bounce} id="play" bind:this={play}><div class="play-head"><div class="level-label" id="levelTitle">{view.levelTitle?.main ?? ""}<span>{view.levelTitle?.subtitle ?? ""}</span></div><span class={view.difficultyClass ?? "chip"} id="difficulty">{view.difficulty ?? ""}</span></div><div class="round-gate" id="roundGate" hidden={view.roundGateHidden}><div class="gate-card"><span class="gate-icon">🎵</span><h2 id="gateMode">{view.gateMode ?? "标准模式"}</h2><p id="gateText">{view.gateText ?? ""}</p><button class="primary" id="startRoundBtn" onclick={() => act("startRoundBtn")}>{view.startLabel ?? "开始挑战 ▶"}</button><small>点开始，听咚咚声，一起闯关！</small></div></div><div class="board"><div class="timer-bar" id="timerBar" class:urgent={view.timerUrgent}><div class="timer-label"><span id="modeName">{view.modeName ?? ""}</span><span id="roundProgress">{view.roundProgress ?? ""}</span><button id="roundReviewBtn" onclick={() => act("roundReviewBtn")} class="result-link" hidden={view.roundReviewBtnHidden}>查看本轮结算</button></div><div class="timer-main"><span id="timerState">{view.timerState ?? "准备好再开始"}</span><b id="timeValue">{view.timeValue ?? "30秒"}</b></div><div class="time-track"><div id="timeFill" style:width={view.timeFillWidth ?? "100%"}></div></div></div><QuestionProgress progress={view.progress} onchoose={i => controller?.chooseQuestion(i)} /><div class="practice-note" id="practiceNote" hidden={view.practiceNoteHidden}><span>专项迁移练习 · <b id="practiceName">{view.practiceName ?? ""}</b></span><button id="exitPracticeBtn" onclick={() => act("exitPracticeBtn")}>退出专项</button></div><div class="targetrow"><div class="target"><b>24</b></div><div class="targetcopy"><b>把四张牌，合成 24！</b><p id="stepCount">{view.stepCount ?? "再合并 3 次"}</p></div></div><div class="board-message" id="boardMessage" role="status" aria-live="polite">{view.boardMessage ?? "先点一张数字牌"}</div><NumberBoard board={view.board} drag={view.drag} bind:element={cards} onchoose={slot => controller?.chooseTile(slot)} ondragstart={(event,slot) => controller?.dragDown(event,slot)} /><div class="operation-preview" id="operationPreview" aria-live="polite" hidden={view.preview?.hidden}><b>{view.preview?.a ?? "数字"}</b><strong>{view.preview?.operator ?? "?"}</strong><span>{view.preview?.b ?? "数字"}</span><strong>=</strong><span>?</span></div><Operators board={view.board} onchoose={operator => controller?.chooseOperator(operator)} /><p class="order-note" id="orderNote">{view.orderNote ?? "也可以先选符号，再把一张牌拖到另一张上。"}</p><div class="kid-controls"><button class="secondary" id="undoMergeBtn" onclick={() => act("undoMergeBtn")} disabled={view.undoDisabled}>↶ 退一步</button><button class="ghost" id="restartBtn" onclick={() => act("restartBtn")} disabled={view.restartDisabled}>↻ 重新来</button><button class="secondary" id="hintBtn" onclick={() => act("hintBtn")} disabled={view.hintDisabled}>{view.hintLabel ?? "💡 提示"}</button></div><div class="hint" id="hint" hidden={view.hintHidden}>{view.hint ?? ""}</div><Feedback feedback={view.feedback} onaction={act} /><details class="move-details" id="moveDetails" open={view.moveDetailsOpen} ontoggle={event => {if(event.currentTarget.open!==view.moveDetailsOpen)controller?.setMoveDetailsOpen(event.currentTarget.open);}} hidden={view.moveDetailsHidden}><summary>看看我刚才怎么算的</summary><ol id="moveLog">{#each view.board?.moves ?? [] as move, i}<li><span>{i + 1}</span>{move}</li>{/each}</ol></details><div class="quiet-actions"><button id="revealBtn" onclick={() => act("revealBtn")} disabled={view.revealDisabled}>想不出？看看解法</button><button id="methodsBtn" onclick={() => act("methodsBtn")}>📖 小窍门手册</button></div></div></section>
<aside class="aside"><section class="journey"><div class="eyebrow">YOUR ADVENTURE</div><h2 id="chapterTitle">{view.chapterTitle ?? "启程 · 灵感草原"}</h2><p>50 关 · 500 道不重复挑战<br>简单与烧脑，下一题都有惊喜。</p><div class="line"><div class="fill" id="journeyFill" style:width={view.journeyFillWidth ?? "0%"}></div></div><footer><span id="journeyCount">{view.journeyCount ?? "已探索 0 / 500"}</span><span>慢慢来，也很棒</span></footer><button class="map-btn" id="mapBtn" onclick={() => act("mapBtn")}>打开探险地图 &nbsp;→</button></section><section class="sidecard"><h3>👆 点三下，就合成</h3><div class="mini-demo"><span>8</span><b>→</b><span>−</span><b>→</b><span>2</span><b>=</b><span>6</span></div><p>先点 8，再点 −，再点 2。<br>两张牌就变成一张 6！</p><p>点错了？随时「退一步」。</p><details><summary>给家长的学习记录</summary><p id="learningCount">{view.learningCount ?? ""}</p><p>每题做完有一句小窍门；完整讲解和同类练习，点开再看。</p></details></section><div class="save-note" id="saveNote">{view.saveNote ?? "◉ 进度自动保存在当前浏览器中。"}</div></aside>
<section class="analysis-panel" id="analysis" bind:this={analysis} hidden={view.analysisHidden}><div class="analysis-head"><div><div class="eyebrow">THE AHA! MOMENT</div><h2>原来，还可以这样算</h2><p id="analysisSubtitle">{view.analysisSubtitle ?? ""}</p></div><span style="font-size:29px">✦</span></div><div class="analysis-body"><Explanation solution={view.solution} lesson={view.lesson} reflection={view.reflection} onsolution={i => controller?.chooseSolution(i)} onmethod={method => controller?.chooseMethod(method)} onpractice={method => controller?.practice(method)} onreflect={choice => controller?.reflect(choice)} /><p class="fineprint">精选解法已去除部分重复写法；不是所有解法的穷举。任何符合规则、结果为 24 的算式都算正确。不同写法可能使用同一种方法。</p></div></section></div><div class="bottom-note"><span>每一次“再试试”，都在让思维发光。</span><span><a href="/games/twenty-four/offline.html" download="24点-数字探险家-原版离线.html">下载原版离线游戏</a> · 无需登录 · 无广告</span></div></main>
<dialog id="mapDialog" bind:this={mapDialog} onclose={() => controller?.dialogClosed("mapDialog")} onclick={event => dismissBackdrop(event,"mapDialog")} onkeydown={event => {if(event.key === "Escape")controller?.escape();}}><div class="modalhead"><div><h2>你的 50 站数字之旅</h2><p>每关 10 题，难易交错。选择关卡会开启新一轮，历史星星保留。</p></div><button class="close" data-close="mapDialog" onclick={() => close("mapDialog")} aria-label="关闭地图">×</button></div><MapContent groups={view.map} onchoose={level => controller?.chooseLevel(level)} /></dialog>
<dialog id="helpDialog" bind:this={helpDialog} onclose={() => controller?.dialogClosed("helpDialog")} onclick={event => dismissBackdrop(event,"helpDialog")} onkeydown={event => {if(event.key === "Escape")controller?.escape();}}><div class="modalhead"><h2>24 点，怎么玩？</h2><button class="close" data-close="helpDialog" onclick={() => close("helpDialog")} aria-label="关闭说明">×</button></div><div class="modalbody rules"><p>👆 <b>点数字 → 点符号 → 点另一张数字。</b>比如点 8、点 −、点 2，两张牌就会变成 6。继续合并，最后只剩一张 24 就成功！不需要输入算式或括号。</p><p>🤏 <b>也可以拖一拖。</b>先选 +、−、×、÷，再把一张牌拖到另一张上。<b>拖起的数在前，放下位置的数在后</b>：拖 8 到 2 上，选 ÷，得到 8÷2=4。</p><p>↶ <b>放心试，随时退。</b>“退一步”恢复上次合并前的牌；“重新来”恢复四张牌。分数和负数也可以继续用，0 不能做除数。</p><p>💡 <b>先试，再听小窍门。</b>提示从线索讲到第一步。答对后有一句方法总结；点开“看看我的解法和小窍门”，还能看多种解法、同类练习。</p><p>🌈 <b>50 关，每关 10 题。</b>简单和难题交错出现。极速每题 10 秒、标准 30 秒、慢速 60 秒。超时自动跳到下一题，本关结算后可以重新挑战。十题都在时间内答对，才算本模式通关。</p><details><summary>家长看看：星星和进度怎么算</summary><p>3 星：未用提示或解析，第一次合成到最后就成功。2 星：用过提示，或合成错误结果后再做对，但没看答案。1 星：看过正确解法后做对。退一步、重新来本身不扣星，也不会重置时间；本题使用提示、看解法和失败尝试的记录会保留。每题取历史最好星级。</p><p>看解析后可标记“已学会”继续；这记录探索进度，但不算答对，也不获得星星。已完成关卡仍可重玩。</p><p>点击“开始挑战”后启用音效和计时；后续题目出现即开始倒计时。答对后停止计时，阅读自己的解析不扣下一题时间。答错仍可在剩余时间内继续试。查看玩法、地图、方法手册或切到后台时暂停；题内提示和正确解法不暂停计时。</p><p>进度、剩余时间和合成到一半的牌保存在当前浏览器中；换设备或清理浏览器数据不会同步。</p></details><button class="primary" data-close="helpDialog" onclick={() => close("helpDialog")}>我会啦，来玩！</button></div></dialog>
<dialog id="methodsDialog" bind:this={methodsDialog} onclose={() => controller?.dialogClosed("methodsDialog")} onclick={event => dismissBackdrop(event,"methodsDialog")} onkeydown={event => {if(event.key === "Escape")controller?.escape();}}><div class="modalhead"><div><h2>24 点方法手册</h2><p>先认线索，再找解法；把“会这道”变成“会这一类”。</p></div><button class="close" data-close="methodsDialog" onclick={() => close("methodsDialog")} aria-label="关闭方法手册">×</button></div><div class="modalbody"><div class="method-route"><strong>没有一个口诀能秒解所有题，但有一套通用找法。</strong><p>提速路线：找因数搭档 → 看邻近数和差额 → 巧用 1、0 → 试分数；每一步都可以从 24 倒推。</p><p>兜底路线：选两数合并，再继续合并；遇到死路就回退。完整试遍合法分支，对有解题一定能找到解。它可靠，但不一定最快。任何合法算式最终都是把两个子结果合并；递归地试遍每次合并，就能覆盖所有括号结构。</p></div><MethodsContent method={view.method} feedback={view.drillFeedback} onmethod={method => controller?.chooseMethod(method)} onpractice={method => controller?.practice(method)} ondrill={choice => controller?.checkDrill(choice)} /></div></dialog><dialog id="summaryDialog" bind:this={summaryDialog} onclose={() => controller?.dialogClosed("summaryDialog")} onclick={event => dismissBackdrop(event,"summaryDialog")} onkeydown={event => {if(event.key === "Escape")controller?.escape();}}><div class="modalhead"><span class="eyebrow">ANOTHER MILESTONE</span><button class="close" data-close="summaryDialog" onclick={() => close("summaryDialog")} aria-label="关闭总结">×</button></div><SummaryContent summary={view.summary} onaction={act} onmethod={method => controller?.chooseMethod(method)} /></dialog><div id="dragGhost" class="drag-ghost" hidden={!view.drag} style:transform={view.drag ? `translate(${view.drag.x}px, ${view.drag.y}px)` : undefined} aria-hidden="true">{#if view.drag?.value}{#if view.drag?.value[1] === 1}<span class="tile-number">{view.drag?.value[0]}</span>{:else}<span class="tile-fraction"><span>{view.drag?.value[0]}</span><span>{view.drag?.value[1]}</span></span>{/if}{/if}</div><div class="celebrate" id="celebrate" aria-hidden="true">{#each view.confetti ?? [] as particle}<i class="confetti" style={`--left:${particle.left}%;--drift:${particle.drift}px;--time:${particle.time}s;--delay:${particle.delay}s;--color:${particle.color}`}></i>{/each}</div>

</div>
